    handleCheckConnection();
    const unsubTickets = subscribeToTickets((data) => {
      setTickets(data);
      setIsLoadingData(false);
      setConnectionStatus('online');
    });
    const unsubCustomers = subscribeToCustomers(setCustomers);
    const unsubMessages = subscribeToMessages(setMessages);
    const unsubTasks = subscribeToTasks(setTasks);
    const unsubMeetings = subscribeToMeetings(setMeetings);
    const unsubKPIs = subscribeToKPIs(setKpis);
    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) setPersonnel(ppl); }
    );
    return () => {
      unsubTickets(); unsubCustomers(); unsubSettings(); unsubMessages();
      unsubTasks(); unsubMeetings(); unsubKPIs();
    };
  }, [handleCheckConnection]);

  /**
   * هوش ارجاع: پیدا کردن فرد مناسب بر اساس تنظیمات سیستم
   */
  const getAutoAssignedPersonnel = (serviceId: string, currentTickets: Ticket[], allPersonnel: Personnel[], config: AppConfig) => {
    const assignment = config.assignmentConfig;
    if (!assignment || assignment.mode === 'manual') return undefined;

    const targetRole = assignment.serviceRoleMap[serviceId];
    if (!targetRole) return undefined;

    const eligiblePersonnel = allPersonnel.filter(p => p.roles.includes(targetRole) && p.status === 'active');
    if (eligiblePersonnel.length === 0) return undefined;

    if (assignment.mode === 'random') {
      return eligiblePersonnel[Math.floor(Math.random() * eligiblePersonnel.length)].id;
    }

    if (assignment.mode === 'auto_load_balance') {
      const counts = eligiblePersonnel.map(p => ({
        id: p.id,
        count: currentTickets.filter(t => t.assignedTo === p.id && t.status !== TicketStatus.COMPLETED && t.status !== TicketStatus.CANCELLED).length
      })).sort((a, b) => a.count - b.count);
      return counts[0].id;
    }
    return undefined;
  };

