      let tempTicketsState = [...tickets];

      for (const ticket of ticketsToSave) {
          const autoId = getAutoAssignedPersonnel(ticket.serviceId, tempTicketsState, personnel, appConfig);
          const finalTicket = { ...ticket, assignedTo: autoId };

          await saveTicketToCloud(finalTicket);
          tempTicketsState.push(finalTicket);

          // اگر ارجاع شد، پیام نوتیفیکیشن بفرست
          if (autoId) {
              const target = personnel.find(p => p.id === autoId);
              if (target) {
