                      id: `notif-${Date.now()}-${Math.random()}`,
                      senderId: 'system',
                      senderName: 'سیستم ارجاع هوشمند',
                      recipientIds: [autoId],
                      recipientNames: [target.fullName],
                      subject: 'ارجاع خودکار تیکت جدید',
                      body: `تیکت شماره ${ticket.id} مربوط به "${ticket.customerName}" به دلیل تخصص و بار کاری مناسب به شما ارجاع داده شد.`,
                      createdAt: new Date().toISOString(),
                      readBy: []
                  };
                  await sendInternalMessage(msg);
              }
          }
      }
