      const ticket = tickets.find(t => t.id === ticketId);
      if (!ticket) return;

      const newTimelineEntry = actionNote ? {
          type: 'comment' as any,
          title: 'یادداشت جدید',
          description: actionNote,
          actorName,
          timestamp: new Date().toISOString(),
          visibility
