          title: `تغییر وضعیت به: ${updates.status}`,
          actorName,
          timestamp: new Date().toISOString(),
          visibility: 'public'
      } : undefined);

      const newTimeline = [...(ticket.timeline || [])];
      if (newTimelineEntry) newTimeline.push(newTimelineEntry);

      await updateTicketInCloud(ticketId, { ...updates, timeline: newTimeline });
