      const ticketsToSave = Array.isArray(ticketOrTickets) ? ticketOrTickets : [ticketOrTickets];

      // شبیه‌سازی وضعیت تیکت‌ها برای محاسبه Load Balance در لحظه ثبت گروهی
      let tempTicketsState = [...tickets];

      for (const ticket of ticketsToSave) {
          const autoId = getAutoAssignedPersonnel(ticket.serviceId, tempTicketsState, personnel, appConfig);
