                    onUpdateServices={saveServicesToCloud} onUpdatePersonnel={savePersonnelToCloud} onUpdateCustomers={() => {}}
                    onEditCustomer={updateCustomerInCloud} onDeleteCustomer={deleteCustomerFromCloud} onUpdateConfig={saveAppConfigToCloud} onLogout={handleLogout}
                  />
