    if (!assignment || assignment.mode === 'manual') return undefined;

    const targetRole = assignment.serviceRoleMap[serviceId];
    if (!targetRole) return undefined;

    const eligiblePersonnel = allPersonnel.filter(p => p.roles.includes(targetRole) && p.status === 'active');
    if (eligiblePersonnel.length === 0) return undefined;

    // حالت تصادفی
    if (assignment.mode === 'random') {
      return eligiblePersonnel[Math.floor(Math.random() * eligiblePersonnel.length)].id;
    }

    // حالت توزیع عادلانه (Load Balance)
    if (assignment.mode === 'auto_load_balance') {
      const counts = eligiblePersonnel.map(p => ({
        id: p.id,
        count: currentTickets.filter(t => t.assignedTo === p.id && t.status !== TicketStatus.COMPLETED && t.status !== TicketStatus.CANCELLED).length
