                <div className="flex flex-col sm:flex-row gap-4 justify-center">
                  <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl">شروع خدمات</button>
                  <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold">پیگیری پرونده</button>
                </div>
              </div>
            )}
            {view === 'new-ticket' && <CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} lang={lang} />}
            {view === 'tracking' && <TrackingView tickets={tickets} services={services} lang={lang} />}
            {view === 'admin' && (
              <>
                {!currentUser ? (
                  <LoginView onLogin={handleLogin} onBack={() => setView('landing')} />
                ) : (
                  <AdminDashboard 
                    lang={lang} currentUser={currentUser} tickets={tickets} services={services} personnel={personnel}
                    customers={customers} messages={messages} tasks={tasks} meetings={meetings} kpis={kpis} config={appConfig}
                    onCreateTicket={handleNewTicket} onUpdateTicket={handleUpdateTicket} onDeleteTicket={deleteTicketFromCloud}
                    onUpdateServices={saveServicesToCloud} onUpdatePersonnel={savePersonnelToCloud} onUpdateCustomers={() => {}}
                    onEditCustomer={updateCustomerInCloud} onDeleteCustomer={deleteCustomerFromCloud} onUpdateConfig={saveAppConfigToCloud} onLogout={handleLogout}
                  />
                )}
              </>
            )}
          </>
        )}
      </main>

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-2 py-1 flex items-center justify-around z-[60]">
        <MobileNavItem active={view === 'landing'} label={t.home} icon={<IconBulb />} onClick={() => setView('landing')} />
        <MobileNavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus />} onClick={() => setView('new-ticket')} />
        <MobileNavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch />} onClick={() => setView('tracking')} />
        <MobileNavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout />} onClick={() => setView('admin')} />
      </div>
    </div>
  );
};

export default App;
